describe('File Upload Validation', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should accept a file smaller than 5MB', () => {
        const fileName = 'small-file.txt'; // Ensure this file is < 5MB
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.get('button[type="submit"]').click();
            cy.get('.success-message').should('be.visible').and('contain', 'File uploaded successfully');
        });
    });

    it('should reject a file larger than 5MB', () => {
        const fileName = 'large-file.txt'; // Ensure this file is > 5MB
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.get('button[type="submit"]').click();
            cy.get('.error-message').should('be.visible').and('contain', 'File size exceeds 5MB limit');
        });
    });
});
